const fs = require("fs");
const path = require("path");
const esbuild = require("esbuild");

function pythonModule(script) {
  const safeScript = script.replace(/<\/script/gi, "<\\/script");
  return [
    "# Generated by desktop/scripts/build-mcp-app.cjs. Do not edit.",
    `IMAGE_REVIEW_BRIDGE_SCRIPT = ${JSON.stringify(safeScript)}`,
    "",
  ].join("\n");
}

function buildMcpApp(options = {}) {
  const root = options.root || path.resolve(__dirname, "..", "..");
  const source = path.join(root, "mcp", "image-review-app.js");
  const output = path.join(root, "crossage_fr", "agent_ui_bridge.py");
  const result = esbuild.buildSync({
    entryPoints: [source],
    bundle: true,
    format: "iife",
    legalComments: "none",
    minify: true,
    platform: "browser",
    target: ["chrome120", "firefox121", "safari17"],
    write: false,
  });
  const content = pythonModule(result.outputFiles[0].text);
  if (options.check) {
    if (!fs.existsSync(output) || fs.readFileSync(output, "utf8") !== content) {
      throw new Error("Generated MCP App bridge is stale. Run npm run build:mcp-app.");
    }
    return output;
  }
  fs.writeFileSync(output, content);
  return output;
}

if (require.main === module) {
  try {
    const output = buildMcpApp({ check: process.argv.includes("--check") });
    console.log(`${process.argv.includes("--check") ? "Verified" : "Built"} ${output}`);
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error));
    process.exit(1);
  }
}

module.exports = { buildMcpApp, pythonModule };
